static INIT: AtomicBool = AtomicBool::new(false);

#[test]
fn gmtiny_matches_c() {
    unsafe {
        melee_modes::tu::gmtiny::ext::HOOK = Some(hook);
    }
    let got = run(SCEN, glue());
    let n = got.lines().filter(|l| l.starts_with("== ")).count();
    assert!(n > 0, "empty scenario");
    if got != EXP {
        let tmp = std::env::temp_dir().join("s497_gmtiny_got.txt");
        let _ = std::fs::write(&tmp, &got);
        panic!("trace differs from the C (wrote {}): {}", tmp.display(), first_diff(&got, EXP));
    }
}
